import java.util.*;

public class Main {
    static int heightChecker(int[] heights) {
        int maxHeight = 0;
        for (int h : heights) maxHeight = Math.max(maxHeight, h);

        int[] counts = new int[maxHeight + 1];
        for (int h : heights) counts[h]++;

        int count = 0, idx = 0;
        for (int value = 0; value <= maxHeight; value++) {
            while (counts[value] > 0) {
                if (heights[idx] != value) count++;
                idx++;
                counts[value]--;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println(heightChecker(new int[]{1, 1, 4, 2, 1, 3}));
        System.out.println(heightChecker(new int[]{1, 2, 3, 4, 5}));
    }
}

